import math

def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(y * y for y in b))
    return dot / (na * nb)

def chunk(text, size=500, overlap=50):
    chunks, start = [], 0
    while start < len(text):
        chunks.append(text[start:start + size])
        start += size - overlap
    return chunks

# 1. 離線索引
docs = {"handbook.md": open("handbook.md", encoding="utf-8").read()}
index = []  # [(來源, 段落, 向量)]
for source, text in docs.items():
    for c in chunk(text):
        index.append((source, c, embed(c)))  # embed(): 呼叫 embedding 模型

# 2. 線上檢索
def retrieve(question, k=3):
    qv = embed(question)
    scored = sorted(index, key=lambda item: cosine(qv, item[2]), reverse=True)
    return scored[:k]

# 3. 生成
def answer(question):
    hits = retrieve(question)
    context = "\n\n".join(f"[{i+1}] ({src}) {text}" for i, (src, text, _) in enumerate(hits))
    prompt = (
        "只根據下列資料回答，並在句尾標註引用編號；資料不足就說不知道。\n\n"
        f"資料：\n{context}\n\n問題：{question}"
    )
    return generate(prompt)  # generate(): 呼叫 LLM
